          throw new SyntaxError(`unexpected character after closing quote at line ${line}`);
        } else if (state === 'start' && character === '"') {
          state = 'quoted';
        } else {
          field += character;
          state = 'unquoted';
        }
      }
      return records;
    },

    end() {
      if (ended) return [];
      ended = true;
      if (state === 'quoted') {
        throw new SyntaxError(`unterminated quoted field at line ${line}`);
      }
      if (state === 'start' && row.length === 0) return [];
      row.push(field);
      const records = [row];
      row = [];
      field = '';
      return records;
    },
  };
}

