    assert.throws(() => createParser({ delimiter }), RangeError);
  }
  assert.deepEqual(parse('a,b', { delimiter: undefined }), [['a', 'b']]);
  const parser = createParser();
  parser.push('left,');
  for (const chunk of [undefined, null, 1, {}, [], Buffer.from('x')]) {
    assert.throws(() => parser.push(chunk), TypeError);
  }
  assert.deepEqual(parser.push('right\n'), [['left', 'right']]);
  assert.deepEqual(parser.end(), []);
  assert.throws(() => parser.push('x'), Error);
  assert.throws(() => parse(1), TypeError);
});

test('syntax errors report physical lines across all split positions', () => {
  const cases = [
    ['"a"x', 1, false], ['"a" ', 1, false],
    ['a\r\n"b"x', 2, false], ['"a\r\nb"x', 2, false],
    ['"a\rb\nc"x', 3, false], ['"a\r\r\nb"x', 3, false],
    ['"', 1, true], ['"a\r\n', 2, true], ['"a\r', 2, true],
    ['a\n"b\r\nc\nd', 4, true], ['"a""', 1, true],
  ];
  for (const [text, line, atEnd] of cases) {
    const matches = error => error instanceof SyntaxError &&
      new RegExp(`\\bline ${line}\\b`).test(error.message);
    for (let split = 0; split <= text.length; split++) {
      const parser = createParser();
      const push = () => {
        parser.push(text.slice(0, split));
        parser.push('');
        parser.push(text.slice(split));
      };
      if (atEnd) {
        push();
        assert.throws(() => parser.end(), matches);
      } else {
        assert.throws(push, matches);
      }
    }
    const parser = createParser();
    const push = () => { for (const unit of text.split('')) parser.push(unit); };
    if (atEnd) { push(); assert.throws(() => parser.end(), matches); }
    else assert.throws(push, matches);
  }
});

test('header conversion retains duplicates, padding and safe special keys', () => {
  const options = Object.freeze({ header: true });
  const objects = parse('x,x,x_2,x,__proto__,constructor,toString\n1,2,3,4,5,6,7,ignored\nshort', options);
  assert.deepEqual(Object.keys(objects[0]), ['x', 'x_2', 'x_2_2', 'x_3', '__proto__', 'constructor', 'toString']);
  assert.deepEqual(Object.values(objects[0]), ['1', '2', '3', '4', '5', '6', '7']);
  assert.deepEqual(Object.values(objects[1]), ['short', '', '', '', '', '', '']);
  assert.equal(Object.getPrototypeOf(objects[0]), Object.prototype);
  for (const key of Object.keys(objects[0])) {
    const descriptor = Object.getOwnPropertyDescriptor(objects[0], key);
    assert.equal(descriptor.enumerable, true);
    assert.equal(descriptor.writable, true);
  }
  assert.deepEqual(parse('', options), []);
  assert.deepEqual(parse('name', options), []);
  assert.deepEqual(parse('a,b', { header: false }), [['a', 'b']]);
  const records = Object.freeze([Object.freeze(['one']), Object.freeze(['two', 'extra'])]);
  const header = Object.freeze(['__proto__', '']);
  const explicit = Object.freeze({ header });
  const result = toObjects(records, explicit);
  assert.deepEqual(Object.values(result[0]), ['one', '']);
  assert.deepEqual(Object.values(result[1]), ['two', 'extra']);
  assert.deepEqual(records, [['one'], ['two', 'extra']]);
  assert.deepEqual(header, ['__proto__', '']);
  assert.deepEqual(toObjects(records, { header: [] }), [{}, {}]);
});
